import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func type(_ field:XCUIElement,_ value:String){field.tap();for c in value{field.typeText(String(c));Thread.sleep(forTimeInterval:0.15)}}
 func option(_ app:XCUIApplication,_ name:String){let q=app.descendants(matching:.any).matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:10),app.debugDescription);q.firstMatch.tap()}
 func testFixedGuestApplyLoginProfileReturnsToExactTargetWithoutSend() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:2){decline.tap()}
 let meal=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA AI browser future meal,")).firstMatch;XCTAssertTrue(meal.waitForExistence(timeout:12),app.debugDescription);meal.tap();tap(app,"Request to join");tap(app,"Continue with email");let email=app.textFields["Email address"];XCTAssertTrue(email.waitForExistence(timeout:10));type(email,"qa-f48-native80@example.invalid");XCTAssertEqual(email.value as? String,"qa-f48-native80@example.invalid");tap(app,"Send code");let code=app.textFields["6-digit code"];XCTAssertTrue(code.waitForExistence(timeout:12),app.debugDescription);type(code,"000000");tap(app,"Verify & continue");let name=app.textFields["First name"];XCTAssertTrue(name.waitForExistence(timeout:12),app.debugDescription);type(name,"QA Guest Flow");let bio=app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","A little about you")).firstMatch;type(bio,"A synthetic guest for the normal application return path.");app.staticTexts["A face. A little story. You."].firstMatch.tap();option(app,"New to London");option(app,"English");option(app,"Food");option(app,"I’m 18 or older and I’ll keep this community welcoming, respectful and friendship-first.");app.scrollViews.firstMatch.swipeUp();XCTAssertTrue(app.buttons["Take your seat"].isHittable,app.debugDescription);tap(app,"Take your seat");let intro=app.textViews["Your introduction"];XCTAssertTrue(intro.waitForExistence(timeout:12),app.debugDescription);XCTAssertEqual(intro.value as? String,"");XCTAssertTrue(app.buttons["Send request"].exists);let target=app.staticTexts.matching(NSPredicate(format:"label BEGINSWITH %@","QA AI browser future meal ·")).firstMatch;XCTAssertTrue(target.exists,app.debugDescription);print("QA_NATIVE80_FIXED_GUEST_PREFIX_EXACT_TARGET_WITHOUT_SEND\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native80-fixed-guest-prefix-exact-apply";a.lifetime = .keepAlways;add(a)
 }
}
